export function TaskQueue({
  queueName = "{{queueName}}",
  stage = "{{stage}}",
  accent = "{{accent}}",
  queueLength = {{queueLength}},
}) {
  const badgeText = { queued: "queued", processing: "processing\u2026", done: "done" }[stage];
  return (
    <div style={{ font: "13px/1.5 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: 18, borderRadius: 12, width: 300, boxSizing: "border-box" }}>
      <p style={{ margin: "0 0 12px", fontWeight: 700 }}>{queueName}</p>
      <div style={{ display: "flex", alignItems: "center", gap: 8, padding: 10, borderRadius: 8, background: "#ffffff", border: "1px solid #24143018" }}>
        <span style={{ width: 10, height: 10, borderRadius: "50%", flexShrink: 0, opacity: stage === "queued" ? .3 : 1, background: accent }} />
        <span style={{ flex: 1, fontWeight: 600, fontSize: 12 }}>Task #1</span>
        <span role="status" style={{ fontSize: 10, padding: "3px 9px", borderRadius: 999, background: "#24143014" }}>{badgeText}</span>
      </div>
      <p style={{ margin: "10px 0 0", fontSize: 10, color: "#24143099" }}>{queueLength} more task(s) waiting behind it</p>
    </div>
  );
}
